const b = $input.first().json.body || {};
const id = String(b.credentialId || '').trim().toUpperCase();
if (!/^PM-\d{6}$/.test(id)) throw new Error('invalid_credential_id');
const hash = b.documentHash ? String(b.documentHash).toLowerCase() : undefined;
if (hash && !/^(0x)?[0-9a-f]{64}$/.test(hash)) throw new Error('invalid_document_hash');
const type = ['qr', 'document'].includes(b.type) ? b.type : 'credential_id';
return [{ json: { credentialId: id, documentHash: hash, type } }];
